package main

import (
	"encoding/csv"
	"encoding/json"
	"fmt"
	"os"
	"strings"
	"time"
)

type Relative struct {
	FirstName    string `json:"FirstName"`
	LastName     string `json:"LastName"`
	Relationship string `json:"Relationship"`
}

type Person struct {
	FirstName string     `json:"FirstName"`
	LastName  string     `json:"LastName"`
	Birthday  string     `json:"Birthday"`
	Age       int        `json:"Age"`
	Relatives []Relative `json:"Relatives"`
}

func main() {
	file, err := os.Open("input/input.csv")
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error opening file: %v\n", err)
		os.Exit(1)
	}
	defer file.Close()

	reader := csv.NewReader(file)
	records, err := reader.ReadAll()
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error reading CSV: %v\n", err)
		os.Exit(1)
	}

	// Skip header
	if len(records) < 2 {
		fmt.Println("[]")
		return
	}

	var people []Person
	refDate := time.Date(2025, 7, 1, 0, 0, 0, 0, time.UTC)

	for _, record := range records[1:] {
		if len(record) < 7 {
			continue
		}

		name := strings.TrimSpace(record[0])
		parts := strings.Fields(name)
		var firstName, lastName string
		if len(parts) >= 2 {
			firstName = parts[0]
			lastName = parts[len(parts)-1]
		} else if len(parts) == 1 {
			firstName = parts[0]
			lastName = ""
		}

		birthdayStr := strings.TrimSpace(record[1])
		birthday, err := time.Parse("1/2/2006", birthdayStr)
		if err != nil {
			continue
		}

		age := refDate.Year() - birthday.Year()
		if refDate.YearDay() < birthday.YearDay() {
			age--
		}

		var relatives []Relative

		father := strings.TrimSpace(record[3])
		if father != "null" && father != "" {
